// Supabase dashboard. Generated by supabase/build-dashboard-functions.mjs — do not edit.

import "jsr:@supabase/functions-js/edge-runtime.d.ts";

// ── inlined from supabase/functions/_shared/openai.ts ──
// Shared OpenAI helpers: retries short rate limits and turns OpenAI errors
// into messages people (and the Firdam team) can act on.

const OPENAI_URL = "https://api.openai.com/v1/chat/completions";

const MAX_RETRIES = 2;

/** POSTs to Chat Completions, retrying brief rate limits (not quota errors). */
async function fetchOpenAI(apiKey: string, body: unknown): Promise<Response> {
  for (let attempt = 0; ; attempt++) {
    const res = await fetch(OPENAI_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
      body: JSON.stringify(body),
    });
    if (res.status !== 429 || attempt >= MAX_RETRIES) return res;

    // Out of credit won't fix itself by waiting — return straight away.
    const text = await res.clone().text();
    if (/insufficient_quota|billing/i.test(text)) return res;

    const retryAfter = Number(res.headers.get("retry-after"));
    const waitMs = Number.isFinite(retryAfter) && retryAfter > 0 ? Math.min(retryAfter * 1000, 8000) : 1500 * (attempt + 1);
    await new Promise((r) => setTimeout(r, waitMs));
  }
}

interface OpenAIFailure {
  /** HTTP status to send back to the app. */
  status: number;
  /** Friendly message for the person using the app. */
  message: string;
  /** Short machine code, e.g. `ai_quota`, `ai_busy`, `ai_key`. */
  code: string;
}

/** Reads a failed OpenAI response, logs the details and returns a friendly error. */
async function describeOpenAIFailure(res: Response): Promise<OpenAIFailure> {
  const text = await res.text().catch(() => "");
  let type = "";
  let detail = "";
  try {
    const parsed = JSON.parse(text) as { error?: { type?: string; code?: string; message?: string } };
    type = parsed.error?.code ?? parsed.error?.type ?? "";
    detail = parsed.error?.message ?? "";
  } catch {
    detail = text.slice(0, 300);
  }
  // Visible in Supabase → Edge Functions → Logs.
  console.error(`OpenAI ${res.status} ${type}: ${detail}`);

  if (res.status === 429 && /insufficient_quota|credit_balance|no credits|billing/i.test(type + detail)) {
    return {
      status: 503,
      code: "ai_quota",
      message:
        "The AI service has run out of credit. The Firdam team needs to add credit to the OpenAI account (platform.openai.com → Billing).",
    };
  }
  if (res.status === 429) {
    return { status: 503, code: "ai_busy", message: "The AI is busy right now. Please try again in a minute." };
  }
  if (res.status === 401 || res.status === 403) {
    return {
      status: 503,
      code: "ai_key",
      message: "The AI key isn't valid. The Firdam team needs to update OPENAI_API_KEY in Supabase.",
    };
  }
  if (res.status === 404 && /model/i.test(detail)) {
    return { status: 503, code: "ai_model", message: "This AI account can't use the selected model yet." };
  }
  return { status: 502, code: "ai_error", message: "The AI couldn't answer just now. Please try again." };
}

// ── translate-library ──
/**
 * One-off: translates the recipe library's descriptions, steps, tips,
 * equipment and storage notes into French and Arabic (names are already
 * done). Opened once with ?token=…; it works through the library in rounds,
 * starting the next round itself, and skips recipes already done — so opening
 * it again just carries on. GET ?token=…&status=1 shows progress.
 */

const MODEL = "gpt-4o-mini";
const LANGS = ["fr", "ar"] as const;
type Lang = (typeof LANGS)[number];
const LANG_NAME: Record<Lang, string> = { fr: "French", ar: "Arabic (Modern Standard, simple everyday words)" };
const ROUND_MS = 100_000;
const PARALLEL = 8;

const url = Deno.env.get("SUPABASE_URL")!;
const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const headers = { apikey: key, Authorization: `Bearer ${key}`, "Content-Type": "application/json" };

interface Recipe {
  id: string;
  name: string;
  short_description: string | null;
  long_description: string | null;
  storage_instructions: string | null;
  reheating_instructions: string | null;
  recipe_steps: { step_number: number; instruction: string }[];
  recipe_tips: { tip: string; display_order: number | null }[];
  recipe_equipment: { equipment: string; display_order: number | null }[];
}

async function rest<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${url}/rest/v1/${path}`, { headers, ...init });
  if (!res.ok) throw new Error(`${path}: ${res.status} ${(await res.text()).slice(0, 200)}`);
  return (await res.json()) as T;
}

/** Recipe ids that still need steps in some language. */
async function todo(): Promise<string[]> {
  const ids: string[] = [];
  for (let from = 0; ; from += 1000) {
    const page = await rest<{ id: string }[]>(`recipes?select=id&order=id&offset=${from}&limit=1000`);
    ids.push(...page.map((r) => r.id));
    if (page.length < 1000) break;
  }
  const done = new Map<string, number>();
  for (let from = 0; ; from += 1000) {
    const page = await rest<{ recipe_id: string; steps: string[] }[]>(
      `recipe_translations?select=recipe_id,steps&order=recipe_id,lang&offset=${from}&limit=1000`,
    );
    for (const r of page) if (r.steps?.length) done.set(r.recipe_id, (done.get(r.recipe_id) ?? 0) + 1);
    if (page.length < 1000) break;
  }
  return ids.filter((id) => (done.get(id) ?? 0) < LANGS.length);
}

async function translate(apiKey: string, source: Record<string, unknown>, lang: Lang): Promise<Record<string, unknown> | null> {
  const res = await fetchOpenAI(apiKey, {
    model: MODEL,
    temperature: 0.2,
    max_tokens: 6000,
    response_format: { type: "json_object" },
    messages: [
      {
        role: "system",
        content:
          `You translate halal family recipes from English into ${LANG_NAME[lang]} for a cooking app. ` +
          "Translate every string value; keep the same JSON keys, and keep every list the same length and order. " +
          "Keep every number, temperature, time and quantity exactly. Keep dish names known by their own name (tajine, biryani…) in their usual form. " +
          "Keep null values as null.",
      },
      { role: "user", content: JSON.stringify(source) },
    ],
  });
  if (!res.ok) {
    console.error("OpenAI", res.status, (await res.text()).slice(0, 300));
    return null;
  }
  try {
    const data = (await res.json()) as { choices?: { message?: { content?: string } }[] };
    return JSON.parse(data.choices?.[0]?.message?.content ?? "{}");
  } catch {
    return null;
  }
}

const list = (a: unknown, n: number): string[] =>
  Array.isArray(a) && a.length === n && a.every((s) => typeof s === "string" && s.trim()) ? (a as string[]) : [];
const text = (a: unknown): string | null => (typeof a === "string" && a.trim() ? a.trim() : null);

async function doRecipe(apiKey: string, id: string): Promise<boolean> {
  const [r] = await rest<Recipe[]>(
    `recipes?id=eq.${id}&select=id,name,short_description,long_description,storage_instructions,reheating_instructions,` +
      `recipe_steps(step_number,instruction),recipe_tips(tip,display_order),recipe_equipment(equipment,display_order)`,
  );
  if (!r) return false;
  const byOrder = <T extends { display_order: number | null }>(a: T[]) => a.slice().sort((x, y) => (x.display_order ?? 0) - (y.display_order ?? 0));
  const source = {
    short_description: r.short_description,
    long_description: r.long_description,
    storage_instructions: r.storage_instructions,
    reheating_instructions: r.reheating_instructions,
    steps: r.recipe_steps.slice().sort((a, b) => a.step_number - b.step_number).map((s) => s.instruction),
    tips: byOrder(r.recipe_tips).map((t) => t.tip),
    equipment: byOrder(r.recipe_equipment).map((e) => e.equipment),
  };
  const out = await Promise.all(LANGS.map((lang) => translate(apiKey, source, lang)));
  const rows = LANGS.map((lang, i) => {
    const t = out[i];
    if (!t) return null;
    const steps = list(t.steps, source.steps.length);
    if (!steps.length && source.steps.length) return null; // try again next time
    return {
      recipe_id: id,
      lang,
      short_description: text(t.short_description),
      long_description: text(t.long_description),
      storage_instructions: text(t.storage_instructions),
      reheating_instructions: text(t.reheating_instructions),
      steps: steps.length ? steps : ["—"],
      tips: list(t.tips, source.tips.length),
      equipment: list(t.equipment, source.equipment.length),
    };
  }).filter(Boolean);
  if (!rows.length) return false;
  await rest(`rpc/save_recipe_translations`, { method: "POST", body: JSON.stringify({ rows }) });
  return rows.length === LANGS.length;
}

/** Works for about ROUND_MS, then starts the next round. */
async function round(apiKey: string, token: string, self: string) {
  const started = Date.now();
  const ids = await todo();
  console.log(`translate-library: ${ids.length} recipes left`);
  if (!ids.length) return;
  let next = 0;
  let failures = 0;
  let saved = 0;
  await Promise.all(
    Array.from({ length: PARALLEL }, async () => {
      while (next < ids.length && Date.now() - started < ROUND_MS && failures < 40) {
        const id = ids[next++];
        try {
          if (await doRecipe(apiKey, id)) saved++;
          else failures++;
        } catch (e) {
          failures++;
          console.error(id, e);
        }
      }
    }),
  );
  if (failures >= 40) {
    console.error("translate-library: too many failures, stopping");
    return;
  }
  // Carry on while there's work and the last round got somewhere.
  if (saved && (next < ids.length || failures)) {
    await fetch(`${self}?token=${encodeURIComponent(token)}`).catch((e) => console.error("next round", e));
  }
}

Deno.serve(async (req) => {
  const params = new URL(req.url).searchParams;
  const token = params.get("token") ?? "";
  const expected = Deno.env.get("TRANSLATE_LIBRARY_TOKEN") ?? "";
  if (!expected || token !== expected) return new Response("Not found", { status: 404 });
  const apiKey = Deno.env.get("OPENAI_API_KEY");
  if (!apiKey) return new Response("No OpenAI key", { status: 500 });

  if (params.get("status")) {
    const left = (await todo()).length;
    return new Response(`${left} recipes left to translate`, { headers: { "Content-Type": "text/plain; charset=utf-8" } });
  }
  const self = `${url}/functions/v1/translate-library`;
  const runtime = (globalThis as { EdgeRuntime?: { waitUntil(p: Promise<unknown>): void } }).EdgeRuntime;
  runtime?.waitUntil(round(apiKey, token, self).catch((e) => console.error("round", e)));
  return new Response(
    "Translating the recipe library into French and Arabic. This keeps going on its own (about an hour). You can close this page.",
    { headers: { "Content-Type": "text/plain; charset=utf-8" } },
  );
});
